# Разворачиваем в чанки: один чанк = (вещество, раздел, текст)
def build_chunks(corpus):
    chunks = []
    for item in corpus:
        for sec, text in item["sections"].items():
            chunks.append({
                "doc_id": item["id"],
                "substance": item["name"],
                "formula": item["formula"],
                "cas": item["cas"],
                "section": sec,
                "text": text,
                "citation": f'{item["name"]} ({item["formula"]}, CAS {item["cas"]}), раздел "{sec}"'
            })
    return chunks

if __name__ == "__main__":
    chunks = build_chunks(CORPUS)
    out = {"meta": {"standard": "ГОСТ 30333-2007 (структура)", "substances": len(CORPUS),
                    "chunks": len(chunks), "nature": "демо-корпус, референс-факты, не проприетарные SDS"},
           "chunks": chunks}
    with open("corpus.json", "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
    print(f"corpus.json: {len(CORPUS)} веществ, {len(chunks)} чанков")
